svg.script:
//
const pathologicalAnswers = [false, true, true, false, true];
const qStates = [true, true, true, true, false]; // Dona Maria (Score 7)
let otherScore = 5;
let tooltipTimeout;

// Inicialização segura
document.addEventListener("DOMContentLoaded", function() {
  updateUI();
});

// Caso o SVG seja embutido diretamente e DOMContentLoaded já tenha ocorrido
if (document.readyState === "interactive" || document.readyState === "complete") {
  updateUI();
}

function setQuestion(qIdx, isSim) {
  qStates[qIdx] = isSim;
  hideCutoffInfo();
  updateUI();
}

function adjustOther(amount) {
  const newScore = otherScore + amount;
  if (newScore >= 0 && newScore <= 10) {
    otherScore = newScore;
    hideCutoffInfo();
    updateUI();
  }
}

function selectScore(S) {
  let sq = 0;
  let so = 0;
  if (S <= 5) {
    sq = S;
    so = 0;
  } else {
    sq = 5;
    so = S - 5;
  }
  otherScore = so;
  for (let i = 0; i < 5; i++) {
    if (i < sq) {
      qStates[i] = pathologicalAnswers[i];
    } else {
      qStates[i] = !pathologicalAnswers[i];
    }
  }
  hideCutoffInfo();
  updateUI();
}

function updateUI() {
  let sq = 0;
  for (let i = 0; i < 5; i++) {
    const isPathological = (qStates[i] === pathologicalAnswers[i]);
    sq += isPathological ? 1 : 0;

    const btnSim = document.getElementById('q' + (i+1) + '-sim');
    const btnNao = document.getElementById('q' + (i+1) + '-nao');
    const weightInd = document.getElementById('q' + (i+1) + '-weight');

    if (qStates[i] === true) {
      btnSim.classList.add('active');
      btnNao.classList.remove('active');
    } else {
      btnSim.classList.remove('active');
      btnNao.classList.add('active');
    }

    if (isPathological) {
      weightInd.style.opacity = '1';
    } else {
      weightInd.style.opacity = '0';
    }
  }

  document.getElementById('other-score-text').textContent = otherScore.toString().padStart(2, '0');

  const totalScore = sq + otherScore;
  updateScoreUI(totalScore);
}

function updateScoreUI(totalScore) {
  // 1. Atualiza Posição do Handle do Slider
  const X = 50 + totalScore * 30;
  document.getElementById('active-handle').setAttribute('transform', 'translate(' + X + ', 121)');

  // 2. Determina Categoria, Cor e Card de Detalhes
  let color = 'var(--c-green)';
  let catText = 'NORMAL';
  let activeGroup = 'detail-normal';

  if (totalScore >= 5 && totalScore <= 9) {
    color = 'var(--c-amber)';
    catText = 'RISCO DE DEPRESSÃO';
    activeGroup = 'detail-risk';
  } else if (totalScore >= 10) {
    color = 'var(--c-red)';
    catText = 'SUSPEITA GRAVE';
    activeGroup = 'detail-severe';
  }

  // 3. Atualiza Display e Cores no Painel
  document.getElementById('score-num').textContent = totalScore.toString().padStart(2, '0');

  const catTitle = document.getElementById('category-title');
  catTitle.textContent = catText;
  catTitle.style.fill = color;

  document.getElementById('card-indicator').setAttribute('fill', color);
  document.getElementById('active-handle-circle').setAttribute('fill', color);

  // 4. Alterna Visibilidade dos Cards de Caso Clínico com Transição Suave
  const groups = ['detail-normal', 'detail-risk', 'detail-severe'];
  for (let i = 0; i < groups.length; i++) {
    const el = document.getElementById(groups[i]);
    if (groups[i] === activeGroup) {
      el.style.display = 'block';
      el.style.opacity = '1';
    } else {
      el.style.opacity = '0';
      el.style.display = 'none';
    }
  }

  // 5. Atualiza Realce Visual das Ticks da Régua
  for (let i = 0; i <= 15; i++) {
    const tick = document.getElementById('tick-' + i);
    const dot = tick.querySelector('.tick-dot');
    const text = tick.querySelector('.tick-text');

    if (i === totalScore) {
      tick.classList.add('active');
      dot.setAttribute('fill', 'var(--c-bg)');
      dot.setAttribute('stroke', color);
      dot.setAttribute('stroke-width', '2.5px');
      dot.setAttribute('r', '5.5');
      dot.style.opacity = '1';
      text.setAttribute('fill', 'var(--c-ink)');
      text.style.fontWeight = '700';
      text.style.fontSize = '12px';
    } else {
      tick.classList.remove('active');
      dot.setAttribute('fill', 'var(--c-ink-muted)');
      dot.removeAttribute('stroke');
      dot.removeAttribute('stroke-width');
      dot.setAttribute('r', '4');
      dot.style.opacity = '0.6';
      text.setAttribute('fill', 'var(--c-ink-muted)');
      text.style.fontWeight = '500';
      text.style.fontSize = '10px';
    }
  }
}

function showCutoffInfo(type) {
  const tt = document.getElementById('cutoff-tooltip');
  const title = document.getElementById('cutoff-tt-title');
  const desc = document.getElementById('cutoff-tt-desc');

  if (type === 1) {
    tt.setAttribute('transform', 'translate(185, 82)');
    title.textContent = 'LIMIAR DE RISCO (5 PONTOS)';
    title.style.fill = 'var(--c-amber)';
    desc.textContent = 'Início da faixa de risco. Requer investigação de sintomas.';
  } else {
    tt.setAttribute('transform', 'translate(335, 82)');
    title.textContent = 'LIMIAR CRÍTICO (10 PONTOS)';
    title.style.fill = 'var(--c-red)';
    desc.textContent = 'Indica suspeita de depressão grave. Intervir rápido.';
  }

  tt.style.opacity = '1';
  tt.style.pointerEvents = 'auto';

  clearTimeout(tooltipTimeout);
  tooltipTimeout = setTimeout(hideCutoffInfo, 4000);
}

// Corrigido typo no nome da função
function hideCutoffInfo() {
  const tt = document.getElementById('cutoff-tooltip');
  tt.style.opacity = '0';
  tt.style.pointerEvents = 'none';
}
//
